content.content:
1	@import "tailwindcss";
2	@import "tw-animate-css";
3	@import "shadcn/tailwind.css";
4	
5	@custom-variant dark (&:is(.dark *));
6	
7	@theme inline {
8	  /* ──────────────────────────────────────────────────────────
9	     INKOS BRAND SWATCHES — Brand Book v1.0 (LOCKED)
10	     Bone · Onyx · Stone · Rust — no additions, no substitutes
11	  ────────────────────────────────────────────────────────── */
12	  --color-bone: #F7F7F5;
13	  --color-onyx: #0F0F0F;
14	  --color-stone: #787774;
15	  --color-rust: #B23A2B;
16	
17	  --font-sans: var(--font-sans), 'Inter', -apple-system, sans-serif;
18	  --font-serif: var(--font-serif), 'Instrument Serif', Georgia, serif;
19	  --font-mono: var(--font-mono), 'JetBrains Mono', monospace;
20	
21	  /* ──────────────────────────────────────────────────────────
22	     SEMANTIC PALETTE — derived from brand swatches
23	     Rule: never pure #FFF or #000. Bone/Onyx only.
24	  ────────────────────────────────────────────────────────── */
25	
26	  /* Bone — 60% usage. Page canvas + sidebar bg. */
27	  --color-background: #F7F7F5;
28	
29	  /* Onyx — 20% usage. Primary text + CTAs. */
30	  --color-foreground: #0F0F0F;
31	
32	  /* Card surface — pure white on Bone, so cards "float" */
33	  --color-card: #FFFFFF;
34	  --color-card-foreground: #0F0F0F;
35	
36	  --color-popover: #FFFFFF;
37	  --color-popover-foreground: #0F0F0F;
38	
39	  /* Primary = Onyx (NOT Rust). Primary CTAs are black. */
40	  --color-primary: #0F0F0F;
41	  --color-primary-foreground: #F7F7F5;
42	
43	  /* Secondary — muted Bone tint */
44	  --color-secondary: oklch(96% 0.003 60);
45	  --color-secondary-foreground: #0F0F0F;
46	
47	  /* Muted — Stone-tinted backgrounds */
48	  --color-muted: oklch(95% 0.003 60);
49	  --color-muted-foreground: #787774;
50	
51	  /* Accent — Rust at 12% opacity for active nav states */
52	  --color-accent: rgba(178, 58, 43, 0.08);
53	  --color-accent-foreground: #B23A2B;
54	
55	  /* Destructive = Rust. Reserved for LIVE pill, active nav, destructive only. */
56	  --color-destructive: #B23A2B;
57	  --color-destructive-foreground: #F7F7F5;
58	
59	  /* ──────────────────────────────────────────────────────────
60	     SEMANTIC STATUS TOKENS
61	  ────────────────────────────────────────────────────────── */
62	  --color-success:            oklch(58% 0.18 145);
63	  --color-success-bg:         oklch(94% 0.05 145);
64	  --color-success-foreground: oklch(26% 0.12 145);
65	  --color-warning:            oklch(70% 0.16 72);
66	  --color-warning-bg:         oklch(94% 0.07 72);
67	  --color-warning-foreground: oklch(36% 0.15 72);
68	
69	  /* Borders — Stone-tinted, visible but light */
70	  --color-border: oklch(89% 0.002 60);
71	  --color-input: oklch(89% 0.002 60);
72	  --color-ring: #0F0F0F;
73	
74	  /* ──────────────────────────────────────────────────────────
75	     SHADOWS — custom (never use Tailwind default shadow-sm/md)
76	  ────────────────────────────────────────────────────────── */
77	
78	  /* Soft border shadow for cards on white */
79	  --shadow-soft: 0 1px 2px 0 oklch(13% 0.015 85 / 0.05), 0 1px 3px 0 oklch(13% 0.015 85 / 0.04);
80	
81	  /* Standard card elevation — visible on off-white page */
82	  --shadow-card: 0 1px 3px 0 oklch(13% 0.015 85 / 0.07), 0 1px 2px -1px oklch(13% 0.015 85 / 0.05);
83	
84	  /* Hover elevation */
85	  --shadow-card-hover: 0 4px 12px -2px oklch(13% 0.015 85 / 0.10), 0 2px 6px -2px oklch(13% 0.015 85 / 0.07);
86	
87	  /* Medium depth for drawers, modals */
88	  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 85 / 0.10), 0 2px 8px -2px oklch(13% 0.015 85 / 0.07);
89	
90	  /* Floating elements — command palette, toasts, tooltips */
91	  --shadow-lift: 0 8px 24px -4px oklch(13% 0.015 85 / 0.14),
92	                 0 4px 10px -2px oklch(13% 0.015 85 / 0.08);
93	
94	  /* Full-screen overlays — modal backdrop shadow on dialog */
95	  --shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 85 / 0.22),
96	                    0 8px 24px -4px oklch(13% 0.015 85 / 0.12);
97	
98	  /* ──────────────────────────────────────────────────────────
99	     RADIUS
100	  ────────────────────────────────────────────────────────── */
101	  --radius: 0.5rem;
102	  --radius-sm: 0.25rem;
103	  --radius-md: 0.5rem;
104	  --radius-lg: 0.75rem;
105	  --radius-xl: 1rem;
106	  --radius-2xl: 1.5rem;   /* 24px — large modals, full-bleed cards */
107	  --radius-full: 9999px;  /* pill buttons, avatar chips, progress bars */
108	
109	  /* ──────────────────────────────────────────────────────────
110	     TYPOGRAPHY
111	  ────────────────────────────────────────────────────────── */
112	  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
113	  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;
114	
115	  /* ──────────────────────────────────────────────────────────
116	     TYPOGRAPHY SCALE — semantic names
117	  ────────────────────────────────────────────────────────── */
118	  --text-display-size:    2.25rem;  /* 36px */
119	  --text-display-height:  2.5rem;   /* 40px */
120	  --text-display-weight:  700;
121	  --text-display-track:   -0.02em;
122	
123	  --text-h1-size:    1.75rem;       /* 28px */
124	  --text-h1-height:  2rem;          /* 32px */
125	  --text-h1-weight:  700;
126	  --text-h1-track:   -0.015em;
127	
128	  --text-h2-size:    1.25rem;       /* 20px */
129	  --text-h2-height:  1.75rem;       /* 28px */
130	  --text-h2-weight:  600;
131	  --text-h2-track:   -0.01em;
132	
133	  --text-h3-size:    1rem;          /* 16px */
134	  --text-h3-height:  1.5rem;        /* 24px */
135	  --text-h3-weight:  600;
136	  --text-h3-track:   -0.005em;
137	
138	  --text-body-size:    0.875rem;    /* 14px */
139	  --text-body-height:  1.25rem;     /* 20px */
140	  --text-body-weight:  400;
141	  --text-body-track:   0em;
142	
143	  --text-body-sm-size:    0.8125rem; /* 13px */
144	  --text-body-sm-height:  1.125rem;  /* 18px */
145	  --text-body-sm-weight:  400;
146	  --text-body-sm-track:   0em;
147	
148	  --text-caption-size:    0.75rem;  /* 12px */
149	  --text-caption-height:  1rem;     /* 16px */
150	  --text-caption-weight:  400;
151	  --text-caption-track:   0em;
152	
153	  --text-micro-size:    0.625rem;   /* 10px */
154	  --text-micro-height:  0.875rem;   /* 14px */
155	  --text-micro-weight:  500;
156	  --text-micro-track:   0.06em;     /* uppercase tracking */
157	
158	  /* ──────────────────────────────────────────────────────────
159	     SPACING CONSTANTS — semantic aliases
160	  ────────────────────────────────────────────────────────── */
161	  --spacing-page-x:      1.5rem;   /* px-6 — desktop page horizontal padding */
162	  --spacing-page-x-sm:   1rem;     /* px-4 — mobile page horizontal padding */
163	  --spacing-page-y:      1.5rem;   /* py-6 — vertical section gap */
164	  --spacing-card-pad:    1.5rem;   /* p-6  — card internal padding */
165	  --spacing-card-gap:    1rem;     /* gap-4 — gap between cards in a grid */
166	  --spacing-section-gap: 1.5rem;   /* space-y-6 — between page sections */
167	  --spacing-field-gap:   1rem;     /* space-y-4 — between form fields */
168	
169	  /* ──────────────────────────────────────────────────────────
170	     ICON SIZE SCALE — reference constants (see lib/design-tokens.ts)
171	  ────────────────────────────────────────────────────────── */
172	  --icon-xs:  0.75rem;   /* 12px */
173	  --icon-sm:  0.875rem;  /* 14px */
174	  --icon-md:  1rem;      /* 16px */
175	  --icon-lg:  1.25rem;   /* 20px */
176	  --icon-xl:  1.5rem;    /* 24px */
177	  --icon-2xl: 2rem;      /* 32px */
178	
179	  /* ──────────────────────────────────────────────────────────
180	     SIDEBAR TOKENS (shadcn sidebar primitives)
181	  ────────────────────────────────────────────────────────── */
182	  --sidebar: #F7F7F5;
183	  --sidebar-background: #F7F7F5;
184	  --sidebar-foreground: #0F0F0F;
185	  --sidebar-primary: #0F0F0F;
186	  --sidebar-primary-foreground: #F7F7F5;
187	  --sidebar-accent: rgba(178, 58, 43, 0.10);
188	  --sidebar-accent-foreground: #B23A2B;
189	  --sidebar-border: oklch(89% 0.002 60);
190	  --sidebar-ring: #0F0F0F;
191	  --sidebar-width: 15rem;
192	  --sidebar-width-mobile: 18rem;
193	  --sidebar-width-icon: 3.5rem;
194	
195	  /* shadcn token aliases */
196	  --color-sidebar: var(--sidebar);
197	  --color-sidebar-foreground: var(--sidebar-foreground);
198	  --color-sidebar-primary: var(--sidebar-primary);
199	  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
200	  --color-sidebar-accent: var(--sidebar-accent);
